shims.ps:
#!/bin/bash
# ps shim: MODE decides what the calling process's tty looks like.
case "$*" in
  *ppid=*tty=*)
    case "${SHIM_PANE_MODE:-none}" in
      none) echo "1 ??" ;;
      *) echo "1 ttys001" ;;
    esac ;;
  *"-o command="*)
    case "${SHIM_ALIVE_PID:-}" in
      "") exit 1 ;;
      *) case "$*" in *"$SHIM_ALIVE_PID"*) echo "bash ${SHIM_ALIVE_COMMAND:-tap-watch.sh run}" ;; *) exit 1 ;; esac ;;
    esac ;;
  *) exit 1 ;;
esac

shims.tmux:
#!/bin/bash
# tmux shim: never a server; answers only what the verbs ask.
cmd="$1"
case "$cmd" in
  list-panes) printf '%%5\t/dev/ttys001\n' ;;
  display-message)
    fmt="${@: -1}"
    case "$fmt" in
      *pane_id*pane_tty*session_name*) printf '%%5\t/dev/ttys001\tsess\t4242:100\n' ;;
      *pane_id*pane_tty*) printf '%%5\t/dev/ttys001\n' ;;
      *pane_id*session_name*) printf '%%5\tsess\t4242:100\n' ;;
      *pane_id*) printf '%%5\n' ;;
      *session_name*) [ "${SHIM_NO_SESSION:-0}" = 1 ] && exit 1; printf 'sess\n' ;;
      *) exit 1 ;;
    esac ;;
  list-windows)
    case "${SHIM_WINDOW:-}" in
      "") exit 0 ;;
      *) case "$*" in *pane_pid*) printf 'watch %s\n' "$SHIM_WINDOW" ;; *) printf 'watch\n' ;; esac ;;
    esac ;;
  new-window) [ "${SHIM_SPAWN:-ok}" = fail ] && exit 1; [ "${SHIM_SPAWN:-ok}" = badpid ] && { printf 'nope\n'; exit 0; }; printf '4242\n' ;;
  kill-window) printf 'kill-window %s\n' "$*" >> "${SHIM_LOG:-/dev/null}"; exit 0 ;;
  set-option) printf 'set-option %s\n' "$*" >> "${SHIM_LOG:-/dev/null}"; exit 0 ;;
  *) exit 1 ;;
esac
